import{_ as l,o as r,c as i,a2 as a}from"./chunks/framework.BXA5Pi9t.js";const _=JSON.parse('{"title":"Ceph Crimson/SeaStor OSD 2020-07-22","description":"","frontmatter":{"title":"Ceph Crimson/SeaStor OSD 2020-07-22","date":"2020-07-22T00:00:00.000Z","updated":"2020-07-24T00:00:00.000Z","tags":["Ceph","分布式存储","CRUSH算法","高可用性","可伸缩性","对象存储","块存储","文件系统存储","一致性","去中心化","性能","Bluestore","BlueFS","RocksDB","OSD","MON","MDS","PG","RADOS","librados","libcephfs","cephfs","rbd","radosgw","RGW","RESTful API","身份验证","授权","加密","纠删码","复制","快照","克隆","瘦分配","iSCSI","Fibre Channel","NFS","CIFS","POSIX","监控","仪表板","管理","编排","自动化","集成","容器化","Kubernetes","Docker","虚拟化","云计算","AWS","Azure","Google Cloud","混合云","多云","存储集群","节点","磁盘","SSD","HDD","JBOD","SAN","NAS","网络","拓扑","失效域","恢复","弹性","负载均衡","缓存","压缩","压缩","分层","性能调优","基准测试","测试","验证"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/Ceph_Crimson_SeaStor_OSD_2020-07-22.md","filePath":"posts/2020/Ceph_Crimson_SeaStor_OSD_2020-07-22.md","lastUpdated":1780460162000}'),o={name:"posts/2020/Ceph_Crimson_SeaStor_OSD_2020-07-22.md"};function t(s,e,n,p,u,h){return r(),i("div",null,[...e[0]||(e[0]=[a('<p>Ceph研发团队于2020年7月22日举行会议，讨论了Ceph存储系统的优化和设计问题。以下是会议的关键细节、主要议题、决定事项和后续行动计划：</p><h3 id="关键细节" tabindex="-1">关键细节 <a class="header-anchor" href="#关键细节" aria-label="Permalink to &quot;关键细节&quot;">​</a></h3><ul><li><strong>参与者</strong>: Ceph研发团队成员</li><li><strong>日期</strong>: 2020年7月22日</li><li><strong>主要议题</strong>: Ceph存储系统优化和设计问题</li></ul><h3 id="讨论的主要议题" tabindex="-1">讨论的主要议题 <a class="header-anchor" href="#讨论的主要议题" aria-label="Permalink to &quot;讨论的主要议题&quot;">​</a></h3><ol><li><p><strong>LBA树的修改</strong>:</p><ul><li>扩展LBA树至32倍，并讨论了相关问题。</li><li>设计了Oman树的布局，计划后续会议中详细讨论。</li></ul></li><li><p><strong>Scrub功能的进展</strong>:</p><ul><li>正在进行Scrub功能的基本工作，包括preemption的测试和可选间距问题的修改。</li></ul></li><li><p><strong>内存管理优化</strong>:</p><ul><li>提出将大部分空间管理移至内存中的想法，通过扫描LBA树来计算每个段的块使用情况，并在内存中维护这些数据。</li></ul></li><li><p><strong>模板和remover问题</strong>:</p><ul><li>仍在解决模板相关的问题，特别是remover的实现，编译器提示remover是不完整的类型。</li></ul></li><li><p><strong>OMAP树布局</strong>:</p><ul><li>讨论了OMAP树的内部节点和叶子节点的布局设计，包括键和值的存储方式。</li></ul></li></ol><h3 id="决定的事项" tabindex="-1">决定的事项 <a class="header-anchor" href="#决定的事项" aria-label="Permalink to &quot;决定的事项&quot;">​</a></h3><ul><li>继续推进Scrub功能的开发和测试。</li><li>实施内存管理优化的方案，并进行性能测试。</li><li>继续解决模板和remover的问题，并在单元测试中验证。</li><li>设计并实现OMAP树的布局，并考虑键和值的最大尺寸问题。</li></ul><h3 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h3><ul><li>进行内存管理优化的性能测试，评估其在实际应用中的表现。</li><li>解决模板和remover的问题，确保代码的完整性和正确性。</li><li>设计和实现OMAP树的布局，并在后续会议中讨论具体的实现细节。</li><li>在接下来的几周内，继续推进上述工作，并根据需要进行调整和优化。</li></ul><h3 id="其他备注" tabindex="-1">其他备注 <a class="header-anchor" href="#其他备注" aria-label="Permalink to &quot;其他备注&quot;">​</a></h3><ul><li>下一周将有一位团队成员休假，但仍可通过电子邮件联系。</li></ul><p>本次会议为Ceph存储系统的优化和设计提供了明确的方向和行动计划，确保了项目的持续进展和团队成员之间的有效沟通。</p>',12)])])}const d=l(o,[["render",t]]);export{_ as __pageData,d as default};
